test('bad credentials are returned without provider payload',async()=>{const f=fixture();const r=await call(f.handler,'/login',{method:'POST',body:{email:'a@b.test',password:'wrong'}});assert.equal(r.status,401);assert.equal(r.body.error.code,'AUTHENTICATION_FAILED');});
test('unknown login fields cannot set a role',async()=>{const f=fixture();const r=await call(f.handler,'/login',{method:'POST',body:{email:'a@b.test',password:'x',role:'admin'}});assert.equal(r.status,422);assert.equal(f.calls.length,0);});
test('reads use caller JWT and fixed tenant; arbitrary query filters are rejected',async()=>{const f=fixture(),c=await login(f);const r=await call(f.handler,'/data/requests?limit=25',{cookie:c});assert.equal(r.status,200);assert.equal(r.body.total,0);const read=f.calls.find(c=>c.url.pathname==='/rest/v1/requests');assert.equal(read.options.headers.Authorization,'Bearer ACCESS_TOKEN');assert.equal(read.options.headers['Accept-Profile'],'dqa_business');const denied=await call(f.handler,'/data/requests?tenant_id=eq.other',{cookie:c});assert.equal(denied.status,422);});
test('logout revokes durable session across separate handler instances',async()=>{const f=fixture(),c=await login(f),other=createBusinessHandler({env,fetchImpl:f.fetchImpl});assert.equal((await call(other,'/me',{cookie:c})).status,200);const r=await call(f.handler,'/logout',{method:'POST',body:{},cookie:c});assert.equal(r.body.server_session_revoked,true);assert.equal((await call(other,'/me',{cookie:c})).body.error.code,'SESSION_REVOKED');});
test('revocation failure is never reported as server logout success',async()=>{const f=fixture(),c=await login(f);f.setFailRevocation(true);const r=await call(f.handler,'/logout',{method:'POST',body:{},cookie:c});assert.equal(r.status,503);assert.equal(r.body.error.code,'SESSION_REVOCATION_UNCONFIRMED');assert.ok(r.headers['set-cookie'].includes('Max-Age=0'));});
test('draft write preserves server tenant and does not retry a dispatched request',async()=>{const f=fixture(),c=await login(f);f.setFailWrite(true);const r=await call(f.handler,'/data/requests',{method:'POST',cookie:c,body:{id:'a6000000-0000-0000-0000-000000000099',data:{purpose:'Synthetic'}}});assert.equal(r.status,503);assert.equal(r.body.error.code,'WRITE_OUTCOME_UNKNOWN');assert.equal(r.body.outcome_unknown,true);assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('/create_request_draft')).length,1);});
test('unknown status fields are rejected by RPC and other resource writes stay gated',async()=>{const f=fixture(),c=await login(f);let r=await call(f.handler,'/data/requests',{method:'POST',cookie:c,body:{id:'a6000000-0000-0000-0000-000000000099',data:{status:'APPROVED'}}});assert.equal(r.status,422);r=await call(f.handler,'/data/equipment',{method:'POST',cookie:c,body:{}});assert.equal(r.status,403);assert.equal(r.body.error.code,'RULE_NOT_APPROVED');});
test('client retries only reads after one single-flight refresh',async()=>{let fresh=false,refreshes=0,reads=0;const client=createBusinessClient(async(url)=>{if(url.endsWith('/refresh')){refreshes++;await new Promise(r=>setTimeout(r,5));fresh=true;return Response.json({authenticated:true});}reads++;return fresh?Response.json({data:[]}):Response.json({error:{code:'SESSION_REFRESH_REQUIRED'}},{status:401});});await Promise.all([client.request('/data/requests'),client.request('/me')]);assert.equal(refreshes,1);assert.equal(reads,4);});
test('client never automatically retries writes on network failure',async()=>{let count=0;const client=createBusinessClient(async()=>{count++;throw Error('offline');});await assert.rejects(client.request('/data/requests',{method:'POST',body:{}}),e=>e.code==='WRITE_OUTCOME_UNKNOWN'&&e.outcomeUnknown);assert.equal(count,1);});

