function deletionFixture({wrong=false,denied=false,lostAck=false}={}){
 const base=fixture(),events=[],key='x.'+Buffer.from(JSON.stringify({role:'service_role',ref:'mmazbwzdiizabikmiily'})).toString('base64url')+'.synthetic';
 const handler=createBusinessHandler({env:{...env,BUSINESS_SUPABASE_SERVICE_ROLE_KEY:key},fetchImpl:async(raw,o)=>{const p=new URL(raw).pathname,b=o.body?JSON.parse(o.body):{};
  if(p.endsWith('/prepare_account_deletion')){events.push({kind:'prepare',body:b,authorization:o.headers.Authorization});return denied?Response.json({message:'ACCESS_ADMIN_REQUIRED'},{status:403}):Response.json({state:'DELETION_PENDING',operation_id:b.p_operation,reauth_granted:true});}
  if(p==='/auth/v1/token'&&b.password==='Synthetic-admin-password'){events.push({kind:'reauth',body:b});return wrong?Response.json({message:'bad credentials'},{status:400}):Response.json({access_token:'EPHEMERAL',refresh_token:'EPHEMERAL_REFRESH',user:{id:U,email:'synthetic@example.invalid'}});}
  if(p==='/auth/v1/logout'){events.push({kind:'logout',authorization:o.headers.Authorization});assert.equal(o.headers.Authorization,'Bearer EPHEMERAL');return new Response(null,{status:204});}
  if(p.endsWith('/complete_account_deletion')){events.push({kind:'complete',body:b,authorization:o.headers.Authorization});assert.equal(o.headers.Authorization,'Bearer '+key);if(lostAck)throw Error('lost completion acknowledgement');return Response.json({operation_id:b.p_operation,kind:'member_delete',state:b.p_outcome==='DELETE'?'SAVED':'REJECTED_NO_WRITE',deleted:b.p_outcome==='DELETE',code:'ADMIN_PASSWORD_INVALID'});}
  return base.fetchImpl(raw,o);
 }});return {base,handler,events};
}
const deletionCommand={action:'delete',operation_id:maintenanceId,id:'a0000000-0000-4000-8000-000000000077',expected_revision:2,password:'Synthetic-admin-password'};
test('account deletion verifies current admin password and never replaces existing login cookie',async()=>{const f=deletionFixture(),cookie=await login(f.base),r=await call(f.handler,'/access',{cookie,method:'POST',body:deletionCommand});assert.equal(r.status,200,JSON.stringify(r.body));assert.equal(r.body.data.deleted,true);assert.deepEqual(f.events.map(e=>e.kind),['prepare','reauth','logout','complete']);assert.equal(f.events[1].body.email,'synthetic@example.invalid');assert.equal(f.events[3].body.p_actor,U);assert.equal(f.events[3].body.p_outcome,'DELETE');assert.ok(!JSON.stringify(f.events[3]).includes(deletionCommand.password));assert.ok(!r.headers['set-cookie']);assert.ok(!JSON.stringify(r.body).includes(deletionCommand.password));assert.equal((await call(f.base.handler,'/me',{cookie})).status,200);});
test('bad manager password returns precise error and terminal no-write completion',async()=>{const f=deletionFixture({wrong:true}),cookie=await login(f.base),r=await call(f.handler,'/access',{cookie,method:'POST',body:deletionCommand});assert.equal(r.status,422);assert.equal(r.body.error.code,'ADMIN_PASSWORD_INVALID');assert.equal(f.events.find(e=>e.kind==='complete').body.p_outcome,'PASSWORD_INVALID');assert.ok(!r.body.outcome_unknown);});
test('nonadmin rejection happens before any password grant',async()=>{const f=deletionFixture({denied:true}),cookie=await login(f.base),r=await call(f.handler,'/access',{cookie,method:'POST',body:deletionCommand});assert.equal(r.status,403);assert.deepEqual(f.events.map(e=>e.kind),['prepare']);});
test('lost deletion completion acknowledgement is not retried',async()=>{const f=deletionFixture({lostAck:true}),cookie=await login(f.base),r=await call(f.handler,'/access',{cookie,method:'POST',body:deletionCommand});assert.equal(r.status,503);assert.equal(r.body.outcome_unknown,true);assert.equal(f.events.filter(e=>e.kind==='complete').length,1);assert.equal(f.events.filter(e=>e.kind==='reauth').length,1);});
test('delete command rejects forged reauth flags, emails and absent password',async()=>{const f=deletionFixture(),cookie=await login(f.base);for(const data of [{...deletionCommand,password_verified:true},{...deletionCommand,email:'target@example.invalid'},{...deletionCommand,actor_id:U},{...deletionCommand,password:''}])assert.equal((await call(f.handler,'/access',{cookie,method:'POST',body:data})).status,422);assert.equal(f.events.length,0);});
test('cross-site delete and GET delete never authenticate a password',async()=>{const f=deletionFixture(),cookie=await login(f.base);assert.equal((await call(f.handler,'/access',{cookie,method:'POST',body:deletionCommand,headers:{origin:'https://foreign.invalid'}})).status,403);assert.equal((await call(f.handler,'/access/delete',{cookie})).status,404);assert.equal(f.events.length,0);});

const recoveryBody={operation_id:'ef000000-0000-4000-8000-000000000030',email:'synthetic@example.invalid'};
function recoveryFixture({available=false,eligible=true,mailStatus=200,prepareFails=false}={}){
 const base=fixture(),events=[];
 const fetchImpl=async(url,o)=>{const p=new URL(url).pathname,b=o.body?JSON.parse(o.body):{};
  if(p.endsWith('/public_account_entry_status')){events.push('entry');assert.equal(o.headers.apikey,env.BUSINESS_SUPABASE_SERVICE_ROLE_KEY);return Response.json({activation_available:available});}
  if(p.endsWith('/prepare_password_recovery')){events.push('prepare');assert.match(b.p_client_hash,/^[a-f0-9]{64}$/);assert.equal(o.headers.Authorization,'Bearer '+env.BUSINESS_SUPABASE_SERVICE_ROLE_KEY);if(prepareFails)throw Error('offline');return Response.json(eligible?{dispatch:true,email:b.p_email,operation_id:b.p_operation}:{dispatch:false});}
  if(p==='/auth/v1/recover'){events.push('mail');assert.equal(new URL(url).searchParams.get('redirect_to'),env.BUSINESS_ORIGIN+'/account/reset-password');assert.deepEqual(b,{email:'synthetic@example.invalid'});assert.equal(o.headers.Authorization,undefined);return Response.json({}, {status:mailStatus});}
  if(p.endsWith('/finish_password_recovery')){events.push(b.p_state);return Response.json(true);}
  return base.fetchImpl(url,o);
 };return {...base,events,handler:createBusinessHandler({env,fetchImpl})};
}
test('public config exposes only boolean entry state without directory or service key',async()=>{const f=recoveryFixture(),r=await call(f.handler,'/config');assert.equal(r.status,200);assert.equal(r.body.activation_available,false);assert.ok(!JSON.stringify(r.body).includes('email'));assert.ok(!JSON.stringify(r.body).includes(env.BUSINESS_SUPABASE_SERVICE_ROLE_KEY));assert.deepEqual(f.events,['entry']);});
test('existing active admin blocks direct signup before any Auth signup',async()=>{const f=recoveryFixture(),r=await call(f.handler,'/activate',{method:'POST',body:{email:'synthetic@example.invalid',password:'Synthetic-password12'}});assert.equal(r.status,403);assert.equal(r.body.error.code,'ACCOUNT_ACTIVATION_CLOSED');assert.deepEqual(f.events,['entry']);assert.equal(f.calls.length,0);});
test('closed activation does not prevent verified invitation claim',async()=>{const f=recoveryFixture(),r=await call(f.handler,'/claim',{method:'POST',body:{access_token:'ACCESS_TOKEN',refresh_token:'REFRESH_TOKEN'}});assert.equal(r.status,200);assert.deepEqual(f.events,[]);});
test('recovery accepted response is identical for eligible, absent and service-failed recipients',async()=>{for(const opts of [{},{eligible:false},{prepareFails:true},{mailStatus:400}]){const f=recoveryFixture(opts),r=await call(f.handler,'/recover',{method:'POST',body:recoveryBody});assert.equal(r.status,202);assert.equal(r.body.accepted,true);assert.ok(!JSON.stringify(r.body).includes('synthetic@example.invalid'));assert.equal(f.events.filter(x=>x==='mail').length,opts.eligible===false||opts.prepareFails?0:1);}});
test('recovery validates CSRF, fields, route and recipient without upstream work',async()=>{const f=recoveryFixture();for(const extra of [{tenant_id:A},{redirect_to:'https://evil.test'},{role:'admin'}])assert.equal((await call(f.handler,'/recover',{method:'POST',body:{...recoveryBody,...extra}})).status,422);assert.equal((await call(f.handler,'/recover',{method:'POST',body:recoveryBody,headers:{origin:'https://evil.test'}})).status,403);assert.equal((await call(f.handler,'/recover',{method:'POST',body:{...recoveryBody,email:'bad'}})).status,422);assert.equal((await call(f.handler,'/recover')).status,405);assert.deepEqual(f.events,[]);});
test('password recovery revokes durable old sessions and current session, clears cookie',async()=>{const f=fixture(),cookie=await login(f),r=await call(f.handler,'/password',{method:'POST',cookie,body:{password:'Synthetic-new-password12',reset_sessions:true}});assert.equal(r.status,200);assert.equal(r.body.signed_out,true);assert.match(r.headers['set-cookie'],/Max-Age=0/);const names=f.calls.map(c=>c.url.pathname.split('/').pop());assert.ok(names.indexOf('revoke_other_own_browser_sessions')<names.lastIndexOf('user'));assert.equal((await call(f.handler,'/me',{cookie})).body.error.code,'SESSION_REVOKED');assert.ok(!JSON.stringify(r.body).includes('Synthetic-new-password12'));});
test('password reset cannot choose a different actor or session',async()=>{const f=fixture(),cookie=await login(f);for(const data of [{actor:U},{session_id:A},{reset_sessions:'true'}])assert.equal((await call(f.handler,'/password',{method:'POST',cookie,body:{password:'Synthetic-new-password12',...data}})).status,422);assert.equal(f.calls.filter(c=>c.options.method==='PUT').length,0);});


test('schedule preview uses the authenticated tenant and creates no operation receipt',async()=>{
 const f=fixture(),cookie=await login(f),r=await call(f.handler,'/planning/preview',{method:'POST',cookie,body:{command:planningBody.command}});assert.equal(r.status,200,JSON.stringify(r.body));assert.equal(r.body.data.scope,'DRAFT_ONLY');
 const c=f.calls.find(x=>x.url.pathname.endsWith('/preview_schedule_draft'));assert.equal(c.options.headers.Authorization,'Bearer ACCESS_TOKEN');assert.equal(JSON.parse(c.options.body).p_tenant,A);assert.ok(!('p_operation' in JSON.parse(c.options.body)));assert.equal(f.calls.filter(x=>/prepare_schedule_draft|execute_schedule_draft/.test(x.url.pathname)).length,0);
});
test('preview rejects cross-site requests, forged fields, anonymous and GET calls',async()=>{
 const f=fixture(),cookie=await login(f),opts={method:'POST',cookie,body:{command:planningBody.command}};assert.equal((await call(f.handler,'/planning/preview',{...opts,headers:{origin:'https://evil.test'}})).status,403);assert.equal((await call(f.handler,'/planning/preview',{...opts,body:{command:planningBody.command,operation_id:maintenanceId}})).status,422);assert.equal((await call(f.handler,'/planning/preview',{method:'POST',body:opts.body})).status,401);assert.equal((await call(f.handler,'/planning/preview',{cookie})).status,405);assert.equal(f.calls.filter(x=>x.url.pathname.endsWith('/preview_schedule_draft')).length,0);
});
test('preview errors remain known no-write outcomes',async()=>{
 const f=fixture(),cookie=await login(f);f.setMaintenanceError('PLANNING_RESOURCE_CONFLICT');const r=await call(f.handler,'/planning/preview',{method:'POST',cookie,body:{command:planningBody.command}});assert.equal(r.status,409);assert.equal(r.body.error.code,'PLANNING_RESOURCE_CONFLICT');assert.ok(!r.body.outcome_unknown);
});

const flowCommand={action:'CREATE',request_id:'ab000000-0000-4000-8000-000000000001',run_id:'ab100000-0000-4000-8000-000000000001',expected_revision:0,source_sha256:'a'.repeat(64),reason:'合成測試',confirmation:'FLOW TEST REQ-TEST'};
test('flow test routes use only the authenticated tenant and caller JWT',async()=>{const f=fixture(),cookie=await login(f);for(const path of ['/flow-tests/preview','/flow-tests/execute']){const body=path.endsWith('preview')?{request_id:flowCommand.request_id}:{operation_id:flowCommand.run_id,command:flowCommand};const r=await call(f.handler,path,{method:'POST',cookie,body});assert.equal(r.status,200,JSON.stringify(r.body));assert.equal(r.body.data.production_mutations,false);}assert.equal((await call(f.handler,'/flow-tests/run/'+flowCommand.request_id,{cookie})).status,200);});
test('flow tests reject arbitrary percentages, role, tenant and virtual timestamps from the browser',async()=>{const f=fixture(),cookie=await login(f);for(const extra of [{percent:100},{tenant_id:A},{virtual_at:'2027-01-01'},{role:'admin'}]){const r=await call(f.handler,'/flow-tests/execute',{method:'POST',cookie,body:{operation_id:flowCommand.run_id,command:{...flowCommand,...extra}}});assert.equal(r.status,422);}assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('/execute_flow_test')).length,0);});
test('lost flow test acknowledgement never dispatches a second write',async()=>{const f=fixture(),cookie=await login(f);f.setFailWrite(true);const r=await call(f.handler,'/flow-tests/execute',{method:'POST',cookie,body:{operation_id:flowCommand.run_id,command:flowCommand}});assert.equal(r.status,503);assert.equal(r.body.outcome_unknown,true);assert.equal(f.calls.filter(c=>c.url.pathname.endsWith('/execute_flow_test')).length,1);});
test('anonymous and cross-site flow test mutations cannot reach the database',async()=>{const f=fixture(),cookie=await login(f);const body={operation_id:flowCommand.run_id,command:flowCommand};assert.equal((await call(f.handler,'/flow-tests/execute',{method:'POST',body})).status,401);assert.equal((await call(f.handler,'/flow-tests/execute',{method:'POST',body,cookie,headers:{origin:'https://attacker.invalid'}})).status,403);});

test('flow-test report download is marked, escaped, nonexecutable and private',async()=>{const f=fixture(),cookie=await login(f);const r=await call(f.handler,'/flow-tests/report/'+flowCommand.request_id,{cookie});assert.equal(r.status,200);assert.match(r.body,/流程測試｜非正式試驗結果/);assert.match(r.body,/&lt;script&gt;/);assert.doesNotMatch(r.body,/<script>/);assert.equal(r.headers['cache-control'],'no-store');assert.match(r.headers['content-disposition'],/^attachment;/);assert.match(r.headers['content-security-policy'],/default-src 'none'/);});

test('new virtual requests use the classified RPC; old clients still create REAL',async()=>{
 const f=fixture(),cookie=await login(f),id='fa000000-0000-4000-8000-000000000010';
 for(const kind of ['VIRTUAL','REAL',undefined]){
  const r=await call(f.handler,'/data/requests',{method:'POST',cookie,body:{id,data:{product_code:'SYNTHETIC'},...(kind?{execution_kind:kind}:{})}});assert.equal(r.status,201,JSON.stringify(r.body));
  const c=f.calls.at(-1);assert.equal(c.url.pathname.split('/').at(-1),kind==='VIRTUAL'?'create_classified_request_draft':'create_request_draft');const args=JSON.parse(c.options.body);assert.equal(args.p_tenant,A);assert.equal(args.p_kind,kind==='VIRTUAL'?'VIRTUAL':undefined);
 }
});
test('invalid purpose and attempts to change a saved classification are rejected before writing',async()=>{
 const f=fixture(),cookie=await login(f),id='fa000000-0000-4000-8000-000000000010';
 let r=await call(f.handler,'/data/requests',{method:'POST',cookie,body:{id,data:{},execution_kind:'DEMO_GUESS'}});assert.equal(r.status,422);assert.equal(r.body.error.code,'EXECUTION_KIND_INVALID');
 r=await call(f.handler,'/data/requests/'+id,{method:'PATCH',cookie,body:{expected_revision:1,data:{},execution_kind:'VIRTUAL'}});assert.equal(r.status,422);assert.ok(!f.calls.some(c=>/create_request_draft|create_classified_request_draft|update_request_draft/.test(c.url.pathname)));
});

function projectBody(n=70){return {operation_id:'ab000000-0000-4000-8000-000000000001',command:{name:'合成專案',execution_kind:'REAL',submit:true,common:{product_code:'SYNTHETIC',draft_signature_data:'data:image/png;base64,SYNTHETIC'},items:Array.from({length:n},(_,i)=>({trial_id:'ac000000-0000-4000-8000-000000000001',name:'Synthetic trial',quantity:i+1,specification:'Spec '+i,acceptance:'Criteria '+i,judgementRequired:'需作判定'}))}};}
test('70 and 100 project items reach authenticated tenant RPC without splitting into partial writes',async()=>{for(const n of [70,100]){const f=fixture(),cookie=await login(f);const r=await call(f.handler,'/projects/execute',{cookie,method:'POST',body:projectBody(n)});assert.equal(r.status,200,JSON.stringify(r.body));const rpc=f.calls.filter(c=>c.url.pathname.endsWith('/execute_project_request'));assert.equal(rpc.length,1);assert.equal(JSON.parse(rpc[0].options.body).p_command.items.length,n);}});
test('project batch supports bounded image plus 100 per-item descriptions above default JSON body size',async()=>{const f=fixture(),cookie=await login(f),body=projectBody(100);body.command.common.draft_signature_data='data:image/png;base64,'+'a'.repeat(1300000);body.command.items.forEach(i=>{i.specification='試'.repeat(3000);i.acceptance='判'.repeat(3000);});const r=await call(f.handler,'/projects/prepare',{cookie,method:'POST',body});assert.equal(r.status,200,JSON.stringify(r.body));});
test('project unknown authority fields, invalid quantities and item 101 rejected before dispatch',async()=>{for(const change of [b=>b.command.tenant_id=A,b=>b.command.items.push(...b.command.items),b=>b.command.items[0].quantity=0,b=>b.command.items[0].actor_id=U,b=>b.command.items[0].specification='a'.repeat(3001)]){const f=fixture(),cookie=await login(f),body=projectBody();change(body);const r=await call(f.handler,'/projects/execute',{cookie,method:'POST',body});assert.equal(r.status,422);assert.equal(f.calls.some(c=>c.url.pathname.endsWith('/execute_project_request')),false);}});
test('project lost acknowledgement returns unknown; rate and conflict are explicit',async()=>{const f=fixture(),cookie=await login(f);f.setFailWrite(true);let r=await call(f.handler,'/projects/execute',{cookie,method:'POST',body:projectBody()});assert.equal(r.body.error.code,'WRITE_OUTCOME_UNKNOWN');assert.equal(r.body.outcome_unknown,true);f.setFailWrite(false);for(const [code,status] of [['PROJECT_RATE_LIMITED',429],['PROJECT_OPERATION_CONFLICT',409]]){f.setMaintenanceError(code);r=await call(f.handler,'/projects/prepare',{cookie,method:'POST',body:projectBody()});assert.equal(r.status,status);assert.equal(r.body.error.code,code);}});

test('snapshot read can return 100 independently detailed project requests within its bounded 8 MiB allowance',async()=>{const f=fixture(),cookie=await login(f);f.setSnapshot({requests:Array.from({length:100},(_,i)=>({id:String(i),specification:'規'.repeat(3000),acceptance:'判'.repeat(3000),form_details:{notes:'說'.repeat(5000)}})),members:[],trials:[]});const r=await call(f.handler,'/snapshot',{cookie});assert.equal(r.status,200,JSON.stringify(r.body.error));assert.equal(r.body.data.requests.length,100);});
